 for(int i=0;i<6;i++){var child=editRoot.transform.Find("Branch"+i);if(!child){var branch=new GameObject("Branch"+i);branch.transform.SetParent(editRoot.transform,false);child=branch.transform;}var lr=child.GetComponent<LineRenderer>();if(!lr)lr=child.gameObject.AddComponent<LineRenderer>();lr.useWorldSpace=false;lr.sharedMaterial=mat;lr.widthMultiplier=.035f;lr.startColor=new Color(.2f,.6f,.02f,.65f);lr.endColor=new Color(.03f,.08f,0,0);lr.positionCount=4;float z=.8f+i*1.15f;float side=i%2==0?1:-1;lr.SetPositions(new[]{new Vector3(0,.08f,z),new Vector3(side*.35f,.08f,z+.2f),new Vector3(side*.7f,.08f,z+.1f),new Vector3(side,.08f,z+.45f)});}
 foreach(var ps in editRoot.GetComponentsInChildren<ParticleSystem>(true))if(ps.name.Trim()=="circles"||ps.name=="glow")ps.gameObject.SetActive(false);PrefabUtility.SaveAsPrefabAsset(editRoot,fissurePath);}finally{PrefabUtility.UnloadPrefabContents(editRoot);}
